    keywords: ['energy', 'cost', 'bill', 'tariff', 'kwh', 'units', 'electricity', 'appliance', 'running cost', 'appliance cost', 'cost per day', 'cost per month', 'cost per year', 'wattage', 'capacity', 'btu', 'ton'],
