        st.push(`Supply current ${fmt(r.Isrc, 4)} A RMS, fundamental ${fmt(r.I1, 4)} A, S = ${fmt(r.S / 1000, 4)} kVA; PF = P / S = ${fmt(r.PF, 4)}, displacement factor = ${fmt(r.DPF, 4)}`);
