      [0, 1, 2].forEach((k) => { o['M' + k] = mg(S[k], sc_); o['A' + k] = sp(S[k], sc_); });
      const M1 = o.M1; if (M1 > 0) { o.u2 = o.M2 / M1 * 100; o.u0 = o.M0 / M1 * 100; }
      if (m === 1) ['a', 'b', 'c'].forEach((n, k) => { o['Pm' + n] = mg(P[k], sc_); o['Pa' + n] = sp(P[k], sc_); });
      else { const back = X.toPhase(S[0], S[1], S[2]); o.err = Math.max.apply(null, back.map((z, k) => X.ab([z[0] - P[k][0], z[1] - P[k][1]]))); }
      if (o.M2 > M1) w.push('The negative-sequence component is larger than the positive-sequence component: the phase order is reversed (a-c-b), or the set is mostly negative sequence. Check the phase labels or the angle signs.');
