      ['a', 'b', 'c'].forEach((k) => { if (!(v[k] > 0)) e.push({ key: k, msg: 'A side must be greater than zero' }); });
      if (e.length) return e;
      const t = [v.a, v.b, v.c].sort((p, q) => q - p);
