      const sumTxt = (cube) => { const p = []; for (let k = 0; k < n; k++) { const b = 1 << (n - 1 - k); if (cube.m & b) p.push(names[k] + ((cube.v & b) ? "'" : '')); } return p; };
      /* Minimise the ON-set of g: all cubes (mask of fixed variables, values on them) lying wholly inside the ON-set, the prime ones, then the cheapest cover by exhaustive search. */
