      const sopT = S.cover.length, sopL = S.cover.reduce((s, c) => s + pc2(c.m), 0), posT = P.cover.length, posL = P.cover.reduce((s, c) => s + pc2(c.m), 0);
      const ones = S.on.length, zeros = R - ones;
