      const bits = (r) => { let s = ''; for (let k = 0; k < n; k++) s += (r >> (n - 1 - k)) & 1; return s; };
      st.push(`Inputs ${names.join(', ')} (${names[0]} is the most significant bit of the row number): ${R} rows`);
      for (let a = 0; a < R; a += 4) st.push('Rows ' + a + ' to ' + Math.min(a + 3, R - 1) + ':  ' + f.slice(a, a + 4).map((v, k) => (a + k) + ' ' + bits(a + k) + ' → ' + v).join('   |   '));
      st.push(`Truth-table number = ${f.map((v, r) => v ? '2^' + r : null).filter(Boolean).join(' + ') || '0'} = ${ttn};  complement F′ = ${ttc}`);
      st.push(`F = Σm(${S.on.join(', ')})  =  ΠM(${f.map((v, r) => v ? null : r).filter((r) => r != null).join(', ')})`);
      st.push(`Prime implicants (${S.pri.length}${S.ess.length ? '; * marks the essential ones' : ''}): ` + (S.pri.length ? S.pri.map((c) => (c.m === 0 ? '1' : lit(c)) + (S.ess.includes(c) ? '*' : '')).join(', ') : 'none'));
      st.push(`Minimal SOP:  F = ${sopTxt}   (${sopT} product term${sopT === 1 ? '' : 's'}, ${sopL} literal${sopL === 1 ? '' : 's'})`);
      st.push(`Minimal POS:  F = ${posTxt}   (${posT} sum term${posT === 1 ? '' : 's'}, ${posL} literal${posL === 1 ? '' : 's'}; from the minimal SOP of F′, by De Morgan)`);
      const Fv = f[row];
