      const g = Math.sqrt(L1 * L2);
      if (i.cpl === 1 && i.M / g > 1 + 1e-12) return [{ key: 'M', msg: `The mutual inductance ${mh(i.M)} mH is larger than √(L1 L2) = ${mh(g)} mH, which would need a coupling coefficient above 1. Check M, L1 and L2` }];
