    if (s.max != null && (s.exMax ? b >= s.max : b > s.max)) { errors.push({ key: s.key, msg: s.label + ' must be ' + (s.exMax ? 'less than ' : 'at most ') + fmt(s.max / FACTOR[s.unit], 4) + dm }); continue; }
