      const r = calculate(def, raw);
      let pass = r.ok && ref.ok;
      if (pass) ref.outputs.forEach((o, n) => { if (!(Math.abs(o.value - r.outputs[n].value) <= 1e-9 * Math.max(1, Math.abs(o.value)))) pass = false; });
